SECOND_ROUTES_FY2 = {'BAKERY__BAKERY': 2, 'BAKERY__BRUNCH_SPOT': 0, 'BAKERY__FARMERS_MARKET': 0, 'BAKERY__ICE_CREAM_SHOP': 0, 'BAKERY__PET_CAFE': 3, 'BAKERY__PIZZA_SHOP': 4, 'BAKERY__SMOOTHIE_SHOP': 0, 'BAKERY__YARN_STORE': 2, 'BRUNCH_SPOT__BAKERY': 0, 'BRUNCH_SPOT__BRUNCH_SPOT': 5, 'BRUNCH_SPOT__FARMERS_MARKET': 5, 'BRUNCH_SPOT__ICE_CREAM_SHOP': 0, 'BRUNCH_SPOT__PET_CAFE': 0, 'BRUNCH_SPOT__PIZZA_SHOP': 0, 'BRUNCH_SPOT__SMOOTHIE_SHOP': 0, 'BRUNCH_SPOT__YARN_STORE': 2, 'FARMERS_MARKET__BAKERY': 0, 'FARMERS_MARKET__BRUNCH_SPOT': 5, 'FARMERS_MARKET__FARMERS_MARKET': 5, 'FARMERS_MARKET__ICE_CREAM_SHOP': 0, 'FARMERS_MARKET__PET_CAFE': 0, 'FARMERS_MARKET__PIZZA_SHOP': 0, 'FARMERS_MARKET__SMOOTHIE_SHOP': 0, 'FARMERS_MARKET__YARN_STORE': 2, 'ICE_CREAM_SHOP__BAKERY': 0, 'ICE_CREAM_SHOP__BRUNCH_SPOT': 0, 'ICE_CREAM_SHOP__FARMERS_MARKET': 0, 'ICE_CREAM_SHOP__ICE_CREAM_SHOP': 6, 'ICE_CREAM_SHOP__PET_CAFE': 0, 'ICE_CREAM_SHOP__PIZZA_SHOP': 7, 'ICE_CREAM_SHOP__SMOOTHIE_SHOP': 6, 'ICE_CREAM_SHOP__YARN_STORE': 2, 'PET_CAFE__BAKERY': 3, 'PET_CAFE__BRUNCH_SPOT': 0, 'PET_CAFE__FARMERS_MARKET': 0, 'PET_CAFE__ICE_CREAM_SHOP': 0, 'PET_CAFE__PET_CAFE': 0, 'PET_CAFE__PIZZA_SHOP': 0, 'PET_CAFE__SMOOTHIE_SHOP': 0, 'PET_CAFE__YARN_STORE': 8, 'PIZZA_SHOP__BAKERY': 4, 'PIZZA_SHOP__BRUNCH_SPOT': 0, 'PIZZA_SHOP__FARMERS_MARKET': 0, 'PIZZA_SHOP__ICE_CREAM_SHOP': 0, 'PIZZA_SHOP__PET_CAFE': 0, 'PIZZA_SHOP__PIZZA_SHOP': 4, 'PIZZA_SHOP__SMOOTHIE_SHOP': 0, 'PIZZA_SHOP__YARN_STORE': 2, 'SMOOTHIE_SHOP__BAKERY': 0, 'SMOOTHIE_SHOP__BRUNCH_SPOT': 0, 'SMOOTHIE_SHOP__FARMERS_MARKET': 0, 'SMOOTHIE_SHOP__ICE_CREAM_SHOP': 6, 'SMOOTHIE_SHOP__PET_CAFE': 0, 'SMOOTHIE_SHOP__PIZZA_SHOP': 7, 'SMOOTHIE_SHOP__SMOOTHIE_SHOP': 6, 'SMOOTHIE_SHOP__YARN_STORE': 9, 'YARN_STORE__BAKERY': 1, 'YARN_STORE__BRUNCH_SPOT': 1, 'YARN_STORE__FARMERS_MARKET': 1, 'YARN_STORE__ICE_CREAM_SHOP': 1, 'YARN_STORE__PET_CAFE': 1, 'YARN_STORE__PIZZA_SHOP': 1, 'YARN_STORE__SMOOTHIE_SHOP': 1, 'YARN_STORE__YARN_STORE': 1}
OPENING_FY2 = "fam"          # tape played before any shop is known
YHAY_FIRST_FY2 = []       # first shops that hand the season to the yhay lineage at step 72
STAY_ON_FAMY_FY2 = True
YHAY_ANY_FY2 = ['YARN_STORE']           # shops that, appearing in the first two, hand it over at step 144

def _get_FY2(v, k, d=None):
    if isinstance(v, dict): return v.get(k, d)
    g = getattr(v, "get", None)
    return g(k, d) if callable(g) else getattr(v, k, d)

def _pass_FY2(obs):
    try:
        farms = list(_get_FY2(obs, "farms", []) or []); p = int(_get_FY2(obs, "player", 0) or 0)
        n = len(_get_FY2(farms[p], "hands", []) or []) if p < len(farms) else 0
    except Exception:
        n = 0
    return {"farmer": ["PASS"], "hands": [["PASS"] for _ in range(n)], "market": []}

def _which_FY2(step, shops):
    if step < 72 or not shops:
        return OPENING_FY2
    first = str(shops[0])
    if step < 144 or len(shops) < 2:
        if first == "YARN_STORE":
            return "famY"
        return "y%d" % FIRST_ROUTES_FY2.get(first, 0) if first in YHAY_FIRST_FY2 else "fam"
    if first == "YARN_STORE":
        return "famY" if STAY_ON_FAMY_FY2 else "y%d" % SECOND_ROUTES_FY2.get("%s__%s" % (shops[0], shops[1]), 1)
    if first in YHAY_FIRST_FY2 or any(str(s) in YHAY_ANY_FY2 for s in shops[:2]):
        return "y%d" % SECOND_ROUTES_FY2.get("%s__%s" % (shops[0], shops[1]), FIRST_ROUTES_FY2.get(first, 0))
    return "fam"

def _agent_fam_yarn2(observation, configuration=None):
    del configuration
    try:
        step = int(_get_FY2(observation, "day", 0) or 0) * 24 + int(_get_FY2(observation, "hour", 0) or 0)
        step = min(max(step, 0), 718)
        shops = list(_get_FY2(_get_FY2(observation, "town", {}) or {}, "unlocked_shops", []) or [])
        tape = _TAPES_FY2[_which_FY2(step, shops)]
        action = copy.deepcopy(tape[min(step, len(tape) - 1)] or {})
        farms = list(_get_FY2(observation, "farms", []) or []); p = int(_get_FY2(observation, "player", 0) or 0)
        expected = len(_get_FY2(farms[p], "hands", []) or []) if p < len(farms) else 0
        hands = list(action.get("hands") or [])
        hands.extend([["PASS"] for _ in range(max(0, expected - len(hands)))])
        action["hands"] = hands[:expected]
        action.setdefault("farmer", ["PASS"]); action.setdefault("market", [])
        return action
    except Exception:
        return _pass_FY2(observation)


