_ROUTES_YH = json.loads(zlib.decompress(base64.b85decode(_ROUTES_DATA_YH)).decode("utf-8"))

def _get_YH(value, key, default=None):
    """Read both normal dictionaries and Kaggle observation objects."""
    if isinstance(value, dict):
        return value.get(key, default)
    getter = getattr(value, "get", None)
    if callable(getter):
        return getter(key, default)
    return getattr(value, key, default)


def route_index_YH(observation, max_shops=2):
    """Choose a tape using zero, one, or two revealed shops."""
    step = _get_YH(observation, "step")
    if step is None:
        step = int(_get_YH(observation, "day", 0) or 0) * 24 + int(
            _get_YH(observation, "hour", 0) or 0
        )
    step = int(step)
    town = _get_YH(observation, "town", {}) or {}
    shops = list(_get_YH(town, "unlocked_shops", []) or [])

    if max_shops >= 2 and step >= SECOND_BRANCH_STEP_YH and len(shops) >= 2:
        return SECOND_ROUTES_YH.get(f"{shops[0]}__{shops[1]}", 0)
    if max_shops >= 1 and step >= FIRST_BRANCH_STEP_YH and shops:
        return FIRST_ROUTES_YH.get(str(shops[0]), 0)
    return 0


def _pass_action_YH(observation):
    player = int(_get_YH(observation, "player", 0) or 0)
    farms = list(_get_YH(observation, "farms", []) or [])
    hands = list(_get_YH(farms[player], "hands", []) or []) if player < len(farms) else []
    return {"farmer": ["PASS"], "hands": [["PASS"] for _ in hands], "market": []}


def action_for_depth_YH(observation, max_shops=2):
    """Return the recorded action while using at most max_shops branches."""
    try:
        raw_step = _get_YH(observation, "step")
        step = int(raw_step) if raw_step is not None else (
            int(_get_YH(observation, "day", 0) or 0) * 24
            + int(_get_YH(observation, "hour", 0) or 0)
        )
        step = min(max(step, 0), 718)
        action = copy.deepcopy(_ROUTES_YH[route_index_YH(observation, max_shops)][step])

        # A tape may have been recorded with a different number of hired hands.
        player = int(_get_YH(observation, "player", 0) or 0)
        farms = list(_get_YH(observation, "farms", []) or [])
        expected = len(_get_YH(farms[player], "hands", []) or []) if player < len(farms) else 0
        hands = list(action.get("hands") or [])
        hands.extend([["PASS"] for _ in range(max(0, expected - len(hands)))])
        action["hands"] = hands[:expected]
        return action
    except Exception:
        return _pass_action_YH(observation)


def _agent_yhay(observation, configuration=None):
    """Kaggle entry point for the two-shop version."""
    del configuration
    return action_for_depth_YH(observation, max_shops=2)


# =======================================================================
# THE SWITCH - the one new decision this file makes.
# =======================================================================

USE_MULTISELECT = True

# {opening shop key: which alternate route to run instead of fam_lead}
# Built from the bake-off table above - only entries where a route other
# than fam_lead clearly won are listed; every other key (or a shop this
# table has never seen) stays on fam_lead, the default.
SWITCH_TABLE = {"YARN_STORE": "fam_yarn2"}

_ROUTE_FUNCS = {
    "fam_yarn2": _agent_fam_yarn2,
    "yhay": _agent_yhay,
}

_selector_state = {"decided": False, "route_name": None, "last_step": None}


def _decide_once(observation, step):
    """Step<=72 only: lock in which route plays the rest of the episode.

    unlocked_shops is empty for a stretch at the start of the season - this
    must NOT lock in "no shop yet" as the final answer the first time it's
    called (step 0). It keeps waiting, turn after turn, until either a shop
    actually appears or step 72 (the deadline every embedded route already
    treats as its own branch point) arrives with none - only then does
    "no shop" become fam_lead by default, permanently.
    """
    if _selector_state["decided"]:
        return
    try:
        shops = list(_get(_get(observation, "town", {}) or {}, "unlocked_shops", []) or [])
        if not shops and step < 72:
            return
        first_shop = str(shops[0]) if shops else None
        _selector_state["route_name"] = SWITCH_TABLE.get(first_shop)
        _selector_state["decided"] = True
    except Exception:
        _selector_state["route_name"] = None
        _selector_state["decided"] = True


def multiselect_agent(observation, configuration=None):
    if not USE_MULTISELECT:
        return _agent_fam_lead(observation, configuration)
    try:
        step = int(_get(observation, "day", 0) or 0) * 24 + int(_get(observation, "hour", 0) or 0)
        step = min(max(step, 0), 718)
        if _selector_state["last_step"] is None or step < _selector_state["last_step"]:
            _selector_state["decided"] = False
            _selector_state["route_name"] = None
        _selector_state["last_step"] = step

        if step <= 72 and not _selector_state["decided"]:
            _decide_once(observation, step)

        route_name = _selector_state["route_name"]
        if route_name and route_name in _ROUTE_FUNCS:
            return _ROUTE_FUNCS[route_name](observation, configuration)
        return _agent_fam_lead(observation, configuration)
    except Exception:
        return _agent_fam_lead(observation, configuration)


# The framework picks the LAST callable in this module's namespace - not a
# function named `agent` (kaggle_environments/agent.py:64). Keep this last.
agent = multiselect_agent
